from __future__ import annotations

import hashlib
import logging
from collections.abc import Sequence
from dataclasses import dataclass
from datetime import datetime, timedelta
from typing import TYPE_CHECKING, Any

from django.contrib.auth import get_user_model
from django.db import transaction
from django.db.models import Prefetch, QuerySet
from django.utils import timezone
from django.utils.dateparse import parse_datetime

from events.media_services import MediaStorageService
from events.models import Event, EventMedia

from .models import (
    FrameDevice,
    FrameDeviceSession,
    FrameEventTag,
    FrameMediaTag,
    FrameTag,
)

if TYPE_CHECKING:
    from django.contrib.auth.models import AbstractBaseUser

User = get_user_model()


logger = logging.getLogger(__name__)


@dataclass
class FeedItem:
    id: str
    type: str
    payload: dict[str, Any]


class FrameAuthenticationService:
    """Helpers to ensure each device has a backing auth user and session."""

    @staticmethod
    @transaction.atomic
    def ensure_device_user(device: FrameDevice) -> AbstractBaseUser:
        """Create or fetch the service user tied to this device."""
        if device.auth_user and device.auth_user.is_active:
            return device.auth_user

        username = f"frame-{device.id}"
        email = f"{username}@frames.local"
        user, created = User.objects.get_or_create(
            username=username,
            defaults={
                "email": email,
                "is_active": True,
                "is_staff": False,
                "is_superuser": False,
            },
        )
        if created:
            user.set_unusable_password()
            user.save(update_fields=["password"])

        device.auth_user = user
        device.save(update_fields=["auth_user"])
        return user

    @staticmethod
    @transaction.atomic
    def record_session(device: FrameDevice, refresh_token) -> FrameDeviceSession:
        """Persist refresh token metadata for revocation tracking."""
        jti = str(refresh_token["jti"])
        expiry = timezone.make_aware(datetime.fromtimestamp(int(refresh_token["exp"])))
        session, _created = FrameDeviceSession.objects.update_or_create(
            device=device,
            refresh_token_jti=jti,
            defaults={
                "refresh_token_expiry": expiry,
                "is_active": True,
                "last_refreshed": timezone.now(),
                "revoked_at": None,
            },
        )
        return session


class FrameContentService:
    """Build device-specific content feeds from media and events."""

    MEDIA_LIMIT = 100
    EVENT_LIMIT = 40

    @staticmethod
    def parse_since(value: str | None) -> datetime | None:
        if not value:
            return None
        parsed = parse_datetime(value)
        if not parsed:
            return None
        if timezone.is_naive(parsed):
            parsed = timezone.make_aware(parsed)
        return parsed

    @staticmethod
    def _active_tags(device: FrameDevice) -> QuerySet[FrameTag]:
        return device.subscribed_tags.filter(is_active=True)

    @classmethod
    def _media_queryset(
        cls,
        device: FrameDevice,
        tags: Sequence[FrameTag],
        since: datetime | None,
    ) -> QuerySet[EventMedia]:
        qs = (
            # nosemgrep: clancal.security.event-objects-bypass-secure-manager
            EventMedia.objects.filter(event__family_group=device.family)
            .select_related("event", "uploaded_by")
            .prefetch_related(
                Prefetch(
                    "frame_tag_links",
                    queryset=FrameMediaTag.objects.select_related("tag"),
                )
            )
            .order_by("-uploaded_at")
        )
        if tags:
            qs = qs.filter(frame_tag_links__tag__in=tags).distinct()
        if since:
            qs = qs.filter(uploaded_at__gte=since)
        return qs[: cls.MEDIA_LIMIT]

    @classmethod
    def _event_queryset(
        cls,
        device: FrameDevice,
        tags: Sequence[FrameTag],
        since: datetime | None,
    ) -> QuerySet[Event]:
        now = timezone.now() - timedelta(days=1)
        qs = (
            # nosemgrep: clancal.security.event-objects-bypass-secure-manager
            Event.objects.filter(family_group=device.family, end_time__gte=now)
            .select_related("creator")
            .prefetch_related(
                Prefetch(
                    "frame_tag_links",
                    queryset=FrameEventTag.objects.select_related("tag"),
                )
            )
            .order_by("start_time")
        )
        if tags:
            qs = qs.filter(frame_tag_links__tag__in=tags).distinct()
        if since:
            qs = qs.filter(updated_at__gte=since)
        return qs[: cls.EVENT_LIMIT]

    @staticmethod
    def _media_item(device: FrameDevice, media: EventMedia) -> FeedItem:
        tags = [link.tag.slug for link in media.frame_tag_links.all()]
        storage = MediaStorageService
        url = storage.generate_presigned_url(media.file_key)
        thumbnail_url = (
            storage.generate_presigned_url(media.thumbnail_key)
            if media.thumbnail_key
            else None
        )
        base_payload: dict[str, Any] = {
            "id": str(media.id),
            "type": "video" if media.media_type == "VIDEO" else "image",
            "url": url,
            "thumbnailUrl": thumbnail_url,
            "mimeType": media.content_type,
            "durationMs": media.duration * 1000
            if media.duration
            else device.image_duration_ms,
            "tags": tags,
            "caption": media.caption,
            "uploadedAt": media.uploaded_at.isoformat(),
        }
        if media.media_type != "VIDEO":
            base_payload["durationMs"] = device.image_duration_ms
        else:
            base_payload["muted"] = device.mute_videos
            base_payload["maxDurationMs"] = min(
                device.max_video_duration_ms,
                base_payload["durationMs"],
            )
        return FeedItem(
            id=str(media.id), type=base_payload["type"], payload=base_payload
        )

    @staticmethod
    def _event_item(event: Event) -> FeedItem:
        tags = [link.tag.slug for link in event.frame_tag_links.all()]
        payload: dict[str, Any] = {
            "id": str(event.id),
            "type": "event",
            "title": event.title,
            "description": event.description,
            "location": event.location,
            "start": event.start_time.isoformat(),
            "end": event.end_time.isoformat(),
            "updatedAt": event.updated_at.isoformat(),
            "tags": tags,
        }
        payload["allDay"] = (event.end_time - event.start_time).total_seconds() >= 86340
        return FeedItem(id=str(event.id), type="event", payload=payload)

    @classmethod
    def build_feed(
        cls,
        device: FrameDevice,
        *,
        since: str | None = None,
    ) -> dict[str, Any]:
        since_dt = cls.parse_since(since)
        tags = list(cls._active_tags(device))
        media_items = []
        for media in cls._media_queryset(device, tags, since_dt):
            try:
                media_items.append(cls._media_item(device, media))
            except Exception as exc:
                logger.warning("Failed to include media %s in feed: %s", media.id, exc)
        event_items = [
            cls._event_item(event)
            for event in cls._event_queryset(device, tags, since_dt)
        ]
        items = media_items + event_items
        feed_hash = cls._hash_payload(items)
        config = cls._device_config_payload(device)
        return {
            "items": [item.payload for item in items],
            "config": config,
            "hash": feed_hash,
        }

    @classmethod
    def device_config(cls, device: FrameDevice) -> dict[str, Any]:
        return cls._device_config_payload(device)

    @staticmethod
    def _hash_payload(items: Sequence[FeedItem]) -> str:
        digester = hashlib.sha256()
        for item in items:
            digester.update(item.id.encode("utf-8"))
            primary = (
                item.payload.get("uploadedAt")
                or item.payload.get("updatedAt")
                or item.payload.get("start")
            )
            if primary:
                digester.update(primary.encode("utf-8"))
        return digester.hexdigest()

    @staticmethod
    def _device_config_payload(device: FrameDevice) -> dict[str, Any]:
        return {
            "muteVideos": device.mute_videos,
            "allowVideo": device.allow_video,
            "imageDurationMs": device.image_duration_ms,
            "transitionDurationMs": device.transition_duration_ms,
            "maxVideoDurationMs": device.max_video_duration_ms,
            "workManagerIntervalMinutes": device.work_manager_interval_minutes,
            "quietHours": {
                "enabled": device.quiet_hours_enabled,
                "start": device.quiet_hours_start.isoformat()
                if device.quiet_hours_start
                else None,
                "end": device.quiet_hours_end.isoformat()
                if device.quiet_hours_end
                else None,
            },
            "timezone": device.timezone,
            "tags": [tag.slug for tag in device.subscribed_tags.filter(is_active=True)],
        }

