def _get_subscription_period(
    stripe_subscription: stripe.Subscription | dict[str, Any],
) -> tuple[datetime, datetime]:
    """Extract current period from Stripe subscription items.

    Stripe API v2025+ removed current_period_start/end from the top-level
    Subscription object. These fields now live on subscription items.
    """
    item = stripe_subscription["items"]["data"][0]
    period_start = datetime.fromtimestamp(item["current_period_start"])
    period_end = datetime.fromtimestamp(item["current_period_end"])
    return (
        timezone.make_aware(period_start),
        timezone.make_aware(period_end),
    )


class StripeService:
    """Service class for all Stripe-related operations"""

    @staticmethod
    def initialize_stripe():
        """Initialize Stripe with API key using lazy initialization.

        This method ensures the API key is only set when needed, preventing
        exposure of sensitive credentials in module-level initialization.
        """
        if not stripe.api_key:
            stripe.api_key = settings.STRIPE_SECRET_KEY
            if not stripe.api_key:
                raise ValueError("STRIPE_SECRET_KEY is not configured")

            # Validate API key format and environment
            if stripe.api_key.startswith("sk_test_") and not settings.DEBUG:
                raise ValueError("Test API key detected in production environment")
            elif stripe.api_key.startswith("sk_live_") and settings.DEBUG:
                raise ValueError("Live API key detected in development environment")
            elif not (
                stripe.api_key.startswith("sk_test_")
                or stripe.api_key.startswith("sk_live_")
            ):
                raise ValueError("Invalid Stripe API key format")

    @staticmethod
    def create_customer(user: User) -> StripeCustomer:
        """Create Stripe customer for user"""
        StripeService.initialize_stripe()

        try:
            # Check if customer already exists
            if hasattr(user, "stripe_customer"):
                return user.stripe_customer

            # Create customer in Stripe with idempotency key
            idempotency_key = f"create_customer_{user.id}"
            stripe_customer = stripe.Customer.create(
                email=user.email,
                name=f"{user.first_name} {user.last_name}",
                metadata={"user_id": str(user.id), "username": user.username},
                idempotency_key=idempotency_key,
            )

            # Create customer in database
            customer = StripeCustomer.objects.create(
                user=user, stripe_customer_id=stripe_customer.id
            )

            logger.info(
                f"Created Stripe customer {stripe_customer.id} for user {user.id}"
            )
            return customer

        except stripe.StripeError as e:
            logger.error(f"Stripe error creating customer: {e}")
            raise
        except Exception as e:
            logger.error(f"Error creating Stripe customer: {e}")
            raise

