    def upgrade_subscription(
        subscription: Subscription, new_tier: SubscriptionTier
    ) -> Subscription:
        """Upgrade subscription to a new tier"""
        StripeService.initialize_stripe()

        try:
            # Get current subscription items
            stripe_subscription = stripe.Subscription.retrieve(
                subscription.stripe_subscription_id
            )

            # Update subscription in Stripe
            stripe_subscription = stripe.Subscription.modify(
                subscription.stripe_subscription_id,
                items=[
                    {
                        "id": stripe_subscription["items"]["data"][0].id,
                        "price": new_tier.stripe_price_id,
                    }
                ],
                proration_behavior="create_prorations",
                metadata={
                    "family_id": str(subscription.family.id),
                    "family_name": subscription.family.name,
                    "tier": new_tier.name,
                    "previous_tier": subscription.tier.name,
                },
            )

            # Update subscription in database
            subscription.tier = new_tier
            subscription.status = stripe_subscription.status
            subscription.save()

            logger.info(f"Upgraded subscription {subscription.id} to {new_tier.name}")
            return subscription

        except stripe.StripeError as e:
            logger.error(f"Stripe error upgrading subscription: {e}")
            raise
        except Exception as e:
            logger.error(f"Error upgrading subscription: {e}")
            raise

