            stripe_pm = stripe.PaymentMethod.attach(
                payment_method_id, customer=customer.stripe_customer_id
            )

            # Set as default if requested
            if set_as_default:
                stripe.Customer.modify(
                    customer.stripe_customer_id,
                    invoice_settings={"default_payment_method": payment_method_id},
                )

            # Create in database
            card = stripe_pm.card
            payment_method = PaymentMethod.objects.create(
                customer=customer,
                stripe_payment_method_id=payment_method_id,
                type=stripe_pm.type,
                last4=card.last4 if stripe_pm.type == "card" and card else "",
                brand=card.brand if stripe_pm.type == "card" and card else None,
                is_default=set_as_default,
            )

            logger.info(
                f"Added payment method {payment_method_id} for customer {customer.id}"
            )
            return payment_method

        except stripe.StripeError as e:
            logger.error(f"Stripe error adding payment method: {e}")
            raise
        except Exception as e:
            logger.error(f"Error adding payment method: {e}")
            raise

    @staticmethod
