        """Remove a payment method"""
        StripeService.initialize_stripe()

        try:
            # Detach from Stripe
            stripe.PaymentMethod.detach(payment_method.stripe_payment_method_id)

            # Delete from database
            payment_method.delete()

            logger.info(f"Removed payment method {payment_method.id}")

        except stripe.StripeError as e:
            logger.error(f"Stripe error removing payment method: {e}")
            raise
        except Exception as e:
            logger.error(f"Error removing payment method: {e}")
            raise

    @staticmethod
    def create_billing_portal_session(customer: StripeCustomer, return_url: str) -> str:
        """Create Stripe billing portal session for customer self-service"""
        StripeService.initialize_stripe()

        try:
            session = stripe.billing_portal.Session.create(
                customer=customer.stripe_customer_id, return_url=return_url
            )

            return session.url

        except stripe.StripeError as e:
            logger.error(f"Stripe error creating billing portal session: {e}")
            raise
        except Exception as e:
            logger.error(f"Error creating billing portal session: {e}")
            raise

    @staticmethod
    def sync_subscription_status(subscription: Subscription) -> Subscription:
        """Sync subscription status from Stripe"""
        StripeService.initialize_stripe()

        try:
            # Get subscription from Stripe
            stripe_subscription = stripe.Subscription.retrieve(
                subscription.stripe_subscription_id
            )

            period_start, period_end = _get_subscription_period(stripe_subscription)

            # Update local subscription
            subscription.status = stripe_subscription.status
            subscription.current_period_start = period_start
            subscription.current_period_end = period_end
            subscription.cancel_at_period_end = stripe_subscription.cancel_at_period_end
            subscription.save()

