            raise

    @staticmethod
    def create_invoice_from_stripe(stripe_invoice: dict[str, Any]) -> Invoice | None:
        """Create or update invoice from Stripe webhook data"""
        try:
            # Find subscription
            subscription = Subscription.objects.filter(
                stripe_subscription_id=stripe_invoice["subscription"]
            ).first()

            if not subscription:
                logger.warning(
                    f"Subscription not found for invoice {stripe_invoice['id']}"
                )
                return None

            # Create or update invoice
            invoice, created = Invoice.objects.update_or_create(
                stripe_invoice_id=stripe_invoice["id"],
                defaults={
                    "subscription": subscription,
                    "amount_paid": Decimal(str(stripe_invoice.get("amount_paid", 0)))
                    / Decimal("100"),  # Convert from cents
                    "amount_due": Decimal(str(stripe_invoice.get("amount_due", 0)))
                    / Decimal("100"),
                    "currency": stripe_invoice["currency"],
                    "status": stripe_invoice["status"],
                    "period_start": datetime.fromtimestamp(
