                    "period_end": datetime.fromtimestamp(
                        stripe_invoice["period_end"], tz=dt_timezone.utc
                    ),
                    "pdf_url": stripe_invoice.get("invoice_pdf"),
                },
            )

            action = "Created" if created else "Updated"
            logger.info(f"{action} invoice {invoice.id} from Stripe")
            return invoice

        except Exception as e:
            logger.error(f"Error creating invoice from Stripe: {e}")
            raise

    @staticmethod
    def record_payment_event(
        stripe_event_id: str, event_type: str, data: dict[str, Any]
    ) -> PaymentEvent:
        """Record a payment event for auditing"""
        try:
            event, created = PaymentEvent.objects.get_or_create(
                stripe_event_id=stripe_event_id,
                defaults={"event_type": event_type, "data": data},
            )

            if created:
                logger.info(f"Recorded payment event {stripe_event_id} ({event_type})")

            return event

        except Exception as e:
            logger.error(f"Error recording payment event: {e}")
            raise
