class ServiceConnectionRequestForm(forms.ModelForm):
    """Form for requesting service provider connection."""

    special_instructions = forms.CharField(
        widget=forms.Textarea(attrs={"rows": 3, "class": "form-control"}),
        required=False,
        help_text="Any special instructions or access information for the service provider",
    )

    class Meta:
        model = FamilyServiceConnection
        fields = [
            "services_provided",
            "availability_windows",
            "can_propose_times",
            "requires_confirmation",
            "default_duration",
            "special_instructions",
        ]
        widgets = {
            "services_provided": forms.CheckboxSelectMultiple(
                attrs={"class": "form-check-input"}
            ),
            "default_duration": forms.Select(
                choices=[
                    ("01:00:00", "1 hour"),
                    ("01:30:00", "1.5 hours"),
                    ("02:00:00", "2 hours"),
                    ("02:30:00", "2.5 hours"),
                    ("03:00:00", "3 hours"),
                    ("04:00:00", "4 hours"),
                ],
                attrs={"class": "form-control"},
            ),
        }
        labels = {
            "services_provided": "Services Needed",
            "can_propose_times": "Allow provider to suggest appointment times",
            "requires_confirmation": "Require my confirmation for all appointments",
            "default_duration": "Typical service duration",
        }
        help_texts = {
            "services_provided": "Select all services you need from this provider",
            "can_propose_times": "If enabled, the provider can suggest appointment times for your approval",
            "requires_confirmation": "If enabled, you must confirm all appointments before they are finalized",
        }

    def __init__(self, *args, **kwargs):
        self.provider = kwargs.pop("provider")
        self.family = kwargs.pop("family")
        super().__init__(*args, **kwargs)

        # Filter categories to provider's services
        services_field = self.fields["services_provided"]
        services_field.queryset = self.provider.categories.filter(  # type: ignore[attr-defined]
            is_active=True
        )

        # Set up availability windows field
        self.fields["availability_windows"] = forms.CharField(
            widget=forms.HiddenInput(),
            required=False,
            initial="{}",
        )

        # Add custom availability fields for each day
        days_of_week = [
            ("monday", "Monday"),
            ("tuesday", "Tuesday"),
            ("wednesday", "Wednesday"),
            ("thursday", "Thursday"),
            ("friday", "Friday"),
            ("saturday", "Saturday"),
            ("sunday", "Sunday"),
        ]

        for day_code, day_name in days_of_week:
            self.fields[f"{day_code}_available"] = forms.BooleanField(
                required=False,
                label=day_name,
                widget=forms.CheckboxInput(attrs={"class": "form-check-input"}),
            )
            self.fields[f"{day_code}_start"] = forms.TimeField(
                required=False,
                widget=forms.TimeInput(
                    attrs={"type": "time", "class": "form-control form-control-sm"}
                ),
                initial="09:00",
            )
            self.fields[f"{day_code}_end"] = forms.TimeField(
                required=False,
                widget=forms.TimeInput(
                    attrs={"type": "time", "class": "form-control form-control-sm"}
                ),
                initial="17:00",
            )

    def clean(self):
        cleaned_data = super().clean()
        if cleaned_data is None:
            return None

        # Build availability windows from individual day fields
        availability_windows = {}
        errors = []
        days_of_week = [
            "monday",
            "tuesday",
            "wednesday",
            "thursday",
            "friday",
            "saturday",
            "sunday",
        ]

        for day in days_of_week:
            if cleaned_data.get(f"{day}_available"):
                start_time = cleaned_data.get(f"{day}_start")
                end_time = cleaned_data.get(f"{day}_end")

                if not start_time or not end_time:
                    errors.append(
                        ValidationError(
                            f"{day.capitalize()}: Both start and end times are required when day is enabled"
                        )
                    )
                    continue

                # Validate time ordering
                if start_time >= end_time:
                    errors.append(
                        ValidationError(
                            f"{day.capitalize()}: Start time ({start_time.strftime('%H:%M')}) must be before end time ({end_time.strftime('%H:%M')})"
                        )
                    )
                    continue

                # Validate reasonable business hours (prevent obvious errors)
                if start_time.hour < 6 or end_time.hour > 23:
                    errors.append(
                        ValidationError(
                            f"{day.capitalize()}: Service hours should be between 6:00 AM and 11:00 PM"
                        )
                    )
                    continue

                # Validate minimum service window (at least 30 minutes)
                from datetime import datetime, timedelta

                # Reference date is arbitrary; only the time-of-day delta matters.
                reference_date = datetime(2000, 1, 1).date()
                start_datetime = datetime.combine(reference_date, start_time)
                end_datetime = datetime.combine(reference_date, end_time)
                duration = end_datetime - start_datetime

                if duration < timedelta(minutes=30):
                    errors.append(
                        ValidationError(
                            f"{day.capitalize()}: Service window must be at least 30 minutes"
                        )
                    )
                    continue

                # Validate maximum service window (no more than 12 hours)
                if duration > timedelta(hours=12):
                    errors.append(
                        ValidationError(
                            f"{day.capitalize()}: Service window cannot exceed 12 hours"
                        )
                    )
                    continue

                availability_windows[day] = [
                    f"{start_time.strftime('%H:%M')}-{end_time.strftime('%H:%M')}"
                ]

        # Raise all time validation errors at once
        if errors:
            raise ValidationError(errors)

        cleaned_data["availability_windows"] = availability_windows

        # Ensure at least one service is selected
        if not cleaned_data.get("services_provided"):
            raise ValidationError("Please select at least one service")

        # Ensure at least one availability window is set
        if not availability_windows:
            raise ValidationError("Please set availability for at least one day")

        # Store special instructions in contract_details
        special_instructions = cleaned_data.get("special_instructions", "")
        if special_instructions:
            cleaned_data["contract_details"] = {
                "special_instructions": special_instructions
            }

        return cleaned_data

    def save(self, commit=True):
        instance = super().save(commit=False)

        # Set contract details with special instructions
        special_instructions = self.cleaned_data.get("special_instructions", "")
        if special_instructions:
            instance.contract_details = {"special_instructions": special_instructions}

        if commit:
            instance.save()
            self.save_m2m()

        return instance


class AppointmentResponseForm(forms.Form):
    """Form for responding to provider appointment proposals."""

    RESPONSE_CHOICES = [
        ("CONFIRMED", "Accept Proposed Time"),
        ("RESCHEDULE", "Request Different Time"),
        ("CANCELLED", "Decline Appointment"),
    ]

    response = forms.ChoiceField(
        choices=RESPONSE_CHOICES,
        widget=forms.RadioSelect(attrs={"class": "form-check-input"}),
        label="How would you like to respond?",
    )

    alternative_times = forms.CharField(
        widget=forms.Textarea(
            attrs={
                "rows": 3,
                "class": "form-control",
                "placeholder": "e.g., 'Any weekday after 3pm' or 'Tuesday or Thursday mornings'",
            }
        ),
        required=False,
        label="Suggest alternative times",
        help_text="If requesting a reschedule, please suggest some alternative times that work for you",
    )

    def clean(self):
        cleaned_data = super().clean()
        if cleaned_data is None:
            return None
        response = cleaned_data.get("response")
        alternative_times = cleaned_data.get("alternative_times")

        if response == "RESCHEDULE" and not alternative_times:
            raise ValidationError(
                "Please suggest alternative times when requesting a reschedule"
            )

        return cleaned_data


