class ProviderInvitationForm(forms.ModelForm):
    """Form for inviting service providers to join family services."""

    class Meta:
        model = ProviderFamilyInvite
        fields = [
            "email",
            "provider_name",
            "provider_type",
            "services_needed",
            "invitation_message",
        ]
        widgets = {
            "email": forms.EmailInput(
                attrs={"class": "form-control", "placeholder": "provider@example.com"}
            ),
            "provider_name": forms.TextInput(
                attrs={
                    "class": "form-control",
                    "placeholder": "Provider or Company Name",
                }
            ),
            "provider_type": forms.Select(attrs={"class": "form-control"}),
            "services_needed": forms.CheckboxSelectMultiple(
                attrs={"class": "form-check-input"}
            ),
            "invitation_message": forms.Textarea(
                attrs={
                    "class": "form-control",
                    "rows": 4,
                    "placeholder": "Optional: Add a personal message to your invitation...",
                }
            ),
        }
        labels = {
            "email": "Provider Email Address",
            "provider_name": "Provider Name",
            "provider_type": "Provider Type",
            "services_needed": "Services Needed",
            "invitation_message": "Personal Message (Optional)",
        }
        help_texts = {
            "email": "The email address where the invitation will be sent",
            "provider_name": "Name of the service provider or company",
            "provider_type": "Individual service provider or company",
            "services_needed": "Select the types of services you need from this provider",
            "invitation_message": "Add a personal note to make your invitation more welcoming",
        }

    def __init__(self, *args, **kwargs):
        self.family = kwargs.pop("family", None)
        super().__init__(*args, **kwargs)

        # Filter to active service categories
        services_field = self.fields["services_needed"]
        services_field.queryset = ServiceCategory.objects.filter(  # type: ignore[attr-defined]
            is_active=True
        )

        # Check if provider already exists
        if self.instance and self.instance.pk:
            # Editing existing invitation
            pass
        else:
            # New invitation - check for existing provider
            if "email" in self.data:
                email = self.data.get("email")
                existing_provider = ServiceProvider.objects.filter(email=email).first()
                if existing_provider:
                    self.fields["provider_name"].initial = existing_provider.name
                    self.fields["provider_type"].initial = existing_provider.type

    def clean_email(self):
        email = self.cleaned_data.get("email")

        if not email:
            return email

        # Check if this family already has an invitation for this email
        if self.family:
            existing_invitation = ProviderFamilyInvite.objects.filter(
                family=self.family, email=email, status__in=["PENDING", "ACCEPTED"]
            ).first()

            if existing_invitation:
                if existing_invitation.status == "PENDING":
                    raise ValidationError(
                        f"An invitation is already pending for {email}. "
                        f"It expires on {existing_invitation.expires_at.strftime('%B %d, %Y')}."
                    )
                elif existing_invitation.status == "ACCEPTED":
                    raise ValidationError(
                        f"{email} has already accepted an invitation and is connected to your family."
                    )

        return email

    def clean(self):
        cleaned_data = super().clean()
        if cleaned_data is None:
            return None

        # Ensure at least one service is selected
        services_needed = cleaned_data.get("services_needed")
        if not services_needed:
            raise ValidationError("Please select at least one service category.")

        # Auto-populate provider name if not provided
        if not cleaned_data.get("provider_name") and cleaned_data.get("email"):
            # Extract name from email as fallback
            email = cleaned_data["email"]
            name_part = email.split("@")[0]
            cleaned_data["provider_name"] = (
                name_part.replace(".", " ").replace("_", " ").title()
            )

        return cleaned_data


class ProviderRegistrationForm(forms.ModelForm):
    """Form for provider registration from invitation."""

    confirm_email = forms.EmailField(
        label="Confirm Email Address",
        widget=forms.EmailInput(attrs={"class": "form-control"}),
        help_text="Please confirm your email address",
    )

    terms_accepted = forms.BooleanField(
        label="I agree to the Terms of Service and Privacy Policy",
        widget=forms.CheckboxInput(attrs={"class": "form-check-input"}),
        help_text="You must accept the terms to complete registration",
    )

    class Meta:
        model = ServiceProvider
        fields = [
            "name",
            "type",
            "phone",
            "website",
            "description",
            "categories",
        ]
        widgets = {
            "name": forms.TextInput(attrs={"class": "form-control"}),
            "type": forms.Select(attrs={"class": "form-control"}),
            "phone": forms.TextInput(
                attrs={"class": "form-control", "placeholder": "555-123-4567"}
            ),
            "website": forms.URLInput(
                attrs={"class": "form-control", "placeholder": "https://"}
            ),
            "description": forms.Textarea(attrs={"class": "form-control", "rows": 4}),
            "categories": forms.CheckboxSelectMultiple(
                attrs={"class": "form-check-input"}
            ),
        }
        labels = {
            "name": "Business/Provider Name",
            "type": "Provider Type",
            "phone": "Phone Number",
            "website": "Website (Optional)",
            "description": "Description of Services",
            "categories": "Service Categories",
        }
        help_texts = {
            "name": "Your business name or your name as an individual provider",
            "type": "Are you an individual provider or a company?",
            "phone": "Phone number where families can reach you",
            "website": "Your business website if you have one",
            "description": "Describe the services you provide and what makes you unique",
            "categories": "Select all service categories you provide",
        }

    def __init__(self, *args, **kwargs):
        self.invitation = kwargs.pop("invitation", None)
        super().__init__(*args, **kwargs)

        # Pre-populate fields from invitation
        if self.invitation:
            self.fields["name"].initial = self.invitation.provider_name
            self.fields["type"].initial = self.invitation.provider_type
            self.fields["confirm_email"].initial = self.invitation.email

            # Pre-select categories from invitation
            if self.invitation.services_needed.exists():
                self.fields[
                    "categories"
                ].initial = self.invitation.services_needed.all()

        # Filter to active categories
        categories_field = self.fields["categories"]
        categories_field.queryset = ServiceCategory.objects.filter(  # type: ignore[attr-defined]
            is_active=True
        )

    def clean_confirm_email(self):
        confirm_email = self.cleaned_data.get("confirm_email")

        if self.invitation and confirm_email != self.invitation.email:
            raise ValidationError(
                f"Email must match the invitation email: {self.invitation.email}"
            )

        return confirm_email

    def clean_phone(self):
        phone = self.cleaned_data.get("phone")

        if phone:
            # Basic phone validation (remove common formatting)
            import re

            cleaned_phone = re.sub(r"[^\d+]", "", phone)

            if len(cleaned_phone) < 10:
                raise ValidationError(
                    "Please enter a valid phone number with at least 10 digits."
                )

        return phone

    def clean(self):
        cleaned_data = super().clean()
        if cleaned_data is None:
            return None

        # Ensure at least one category is selected
        categories = cleaned_data.get("categories")
        if not categories:
            raise ValidationError("Please select at least one service category.")

        # Ensure terms are accepted
        if not cleaned_data.get("terms_accepted"):
            raise ValidationError(
                "You must accept the Terms of Service to complete registration."
            )

        return cleaned_data
